"""Read CSV files into lists of typed record dicts."""

import csv


def convert_value(value):
    """Convert a raw CSV string to int, float, bool, or leave it as str."""
    text = value.strip()
    lowered = text.lower()
    if lowered in ("true", "false"):
        return lowered == "true"
    try:
        return int(text)
    except ValueError:
        pass
    try:
        return float(text)
    except ValueError:
        return text


def parse_rows(lines, convert=True):
    """Parse an iterable of CSV lines (header first) into a list of dicts."""
    reader = csv.DictReader(lines)
    records = []
    for row in reader:
        if convert:
            row = {key: convert_value(val) for key, val in row.items()}
        records.append(row)
    return records


def parse_csv(path, convert=True):
    """Parse the CSV file at `path` into a list of dicts."""
    with open(path, newline="", encoding="utf-8") as f:
        return parse_rows(f, convert=convert)

"""Sorting and filtering over lists of record dicts."""

import operator

OPERATORS = {
    "==": operator.eq,
    "!=": operator.ne,
    "<": operator.lt,
    "<=": operator.le,
    ">": operator.gt,
    ">=": operator.ge,
    "contains": lambda a, b: str(b).lower() in str(a).lower(),
}


def sort_records(records, key, reverse=False):
    """Return a new list of records sorted by the field `key`."""
    return sorted(records, key=lambda r: r[key], reverse=reverse)


def filter_records(records, key, op, value):
    """Return records where `record[key] <op> value` holds."""
    compare = OPERATORS[op]
    return [r for r in records if compare(r[key], value)]


def apply_filters(records, conditions):
    """Apply a sequence of (key, op, value) filters, ANDed together."""
    for key, op, value in conditions:
        records = filter_records(records, key, op, value)
    return records

"""Exceptions and input validation shared by the parser and operations."""


class CSVProcessingError(Exception):
    """Base class for all errors raised by csvproc."""


class ParseError(CSVProcessingError):
    """The CSV input is malformed or unreadable."""


class ValidationError(CSVProcessingError):
    """Arguments passed to a csvproc function are invalid."""


def validate_header(fieldnames):
    """Ensure a header row exists, has no blank names, and no duplicates."""
    if not fieldnames:
        raise ParseError("CSV input is empty or has no header row")
    stripped = [name.strip() for name in fieldnames]
    if any(not name for name in stripped):
        raise ParseError("CSV header contains a blank column name")
    seen = set()
    for name in stripped:
        if name in seen:
            raise ParseError(f"CSV header contains duplicate column {name!r}")
        seen.add(name)
    return stripped


def validate_records(records):
    """Ensure `records` is a list of dicts."""
    if not isinstance(records, list):
        raise ValidationError(f"records must be a list, got {type(records).__name__}")
    for i, record in enumerate(records):
        if not isinstance(record, dict):
            raise ValidationError(f"record {i} is not a dict")


def validate_key(records, key):
    """Ensure every record has the field `key`."""
    if not isinstance(key, str) or not key:
        raise ValidationError("key must be a non-empty string")
    for i, record in enumerate(records):
        if key not in record:
            raise ValidationError(f"record {i} has no field {key!r}")


def validate_operator(op, allowed):
    """Ensure `op` is one of the `allowed` operator names."""
    if op not in allowed:
        choices = ", ".join(sorted(allowed))
        raise ValidationError(f"unknown operator {op!r}; expected one of: {choices}")

"""Read CSV files into lists of typed record dicts."""

import csv

from .validation import ParseError, validate_header


def convert_value(value):
    """Convert a raw CSV string to int, float, bool, or leave it as str.

    Empty strings become None so that missing values are explicit.
    """
    if value is None:
        return None
    text = value.strip()
    if not text:
        return None
    lowered = text.lower()
    if lowered in ("true", "false"):
        return lowered == "true"
    try:
        return int(text)
    except ValueError:
        pass
    try:
        return float(text)
    except ValueError:
        return text


def parse_rows(lines, convert=True):
    """Parse an iterable of CSV lines (header first) into a list of dicts.

    Raises ParseError for a missing/invalid header or a row whose column
    count does not match the header.
    """
    reader = csv.reader(lines)
    try:
        header = next(reader, None)
        fieldnames = validate_header(header)
        records = []
        for row in reader:
            if not row:
                continue  # skip blank lines
            if len(row) != len(fieldnames):
                raise ParseError(
                    f"line {reader.line_num}: expected {len(fieldnames)} "
                    f"fields, got {len(row)}"
                )
            values = [convert_value(v) for v in row] if convert else row
            records.append(dict(zip(fieldnames, values)))
    except csv.Error as exc:
        raise ParseError(f"line {reader.line_num}: {exc}") from exc
    return records


def parse_csv(path, convert=True):
    """Parse the CSV file at `path` into a list of dicts."""
    try:
        with open(path, newline="", encoding="utf-8") as f:
            return parse_rows(f, convert=convert)
    except FileNotFoundError as exc:
        raise ParseError(f"file not found: {path}") from exc
    except IsADirectoryError as exc:
        raise ParseError(f"path is a directory: {path}") from exc
    except UnicodeDecodeError as exc:
        raise ParseError(f"file is not valid UTF-8: {path}") from exc

