"""Command-line interface: parse, filter, sort, and print a CSV file."""

import argparse
import csv
import sys

from .operations import OPERATORS, apply_filters, sort_records
from .parser import convert_value, parse_csv
from .validation import CSVProcessingError, ValidationError


def format_value(value):
    """Render a parsed value back to its CSV text form."""
    if value is None:
        return ""
    if isinstance(value, bool):
        return "true" if value else "false"
    return str(value)


def write_records(records, out, columns=None):
    """Write records as CSV to the file object `out`."""
    if columns is None:
        columns = list(records[0]) if records else []
    writer = csv.writer(out, lineterminator="\n")
    writer.writerow(columns)
    for record in records:
        writer.writerow([format_value(record[c]) for c in columns])


def build_parser():
    parser = argparse.ArgumentParser(
        prog="csvproc",
        description="Filter and sort records in a CSV file.",
    )
    parser.add_argument("file", help="path to the input CSV file")
    parser.add_argument(
        "-w", "--where", nargs=3, action="append", default=[],
        metavar=("KEY", "OP", "VALUE"),
        help=f"keep rows where KEY OP VALUE; OP is one of {' '.join(OPERATORS)}. "
             "Repeat to AND several conditions.",
    )
    parser.add_argument("-s", "--sort", metavar="KEY", help="sort by this column")
    parser.add_argument("-r", "--reverse", action="store_true", help="sort descending")
    parser.add_argument("-c", "--columns", help="comma-separated columns to output")
    parser.add_argument("-n", "--limit", type=int, help="output at most N rows")
    parser.add_argument("--count", action="store_true", help="print only the row count")
    parser.add_argument("-o", "--output", help="write CSV here instead of stdout")
    return parser


def run(args, stdout):
    records = parse_csv(args.file)
    conditions = [(key, op, convert_value(value)) for key, op, value in args.where]
    records = apply_filters(records, conditions)
    if args.sort:
        records = sort_records(records, args.sort, reverse=args.reverse)
    if args.limit is not None:
        if args.limit < 0:
            raise ValidationError("--limit must be non-negative")
        records = records[:args.limit]

    if args.count:
        print(len(records), file=stdout)
        return

    columns = None
    if args.columns:
        columns = [c.strip() for c in args.columns.split(",") if c.strip()]
        known = set(records[0]) if records else set(columns)
        unknown = [c for c in columns if c not in known]
        if unknown:
            raise ValidationError(f"unknown column(s): {', '.join(unknown)}")

    if args.output:
        try:
            with open(args.output, "w", newline="", encoding="utf-8") as f:
                write_records(records, f, columns)
        except OSError as exc:
            raise CSVProcessingError(f"cannot write {args.output}: {exc.strerror or exc}") from exc
    else:
        write_records(records, stdout, columns)


def main(argv=None, stdout=None, stderr=None):
    """Entry point. Returns a process exit code."""
    stdout = stdout or sys.stdout
    stderr = stderr or sys.stderr
    args = build_parser().parse_args(argv)
    try:
        run(args, stdout)
    except CSVProcessingError as exc:
        print(f"error: {exc}", file=stderr)
        return 1
    return 0

