    def test_repeated_where(self):
        args = build_parser().parse_args(["f.csv", "-w", "a", "==", "1", "-w", "b", ">", "2"])
        assert args.where == [["a", "==", "1"], ["b", ">", "2"]]

    def test_missing_file_arg_exits(self):
