            build_parser().parse_args([])


class TestMain:
    @pytest.fixture
    def csv_file(self, tmp_path):
        path = tmp_path / "in.csv"
        path.write_text("id,name,age\n1,Ann,30\n2,Bo,25\n3,Cy,\n", encoding="utf-8")
        return str(path)

    def call(self, argv):
        out, err = io.StringIO(), io.StringIO()
        code = main(argv, stdout=out, stderr=err)
        return code, out.getvalue(), err.getvalue()

    def test_passthrough(self, csv_file):
        code, out, _ = self.call([csv_file])
        assert code == 0
        assert out == "id,name,age\n1,Ann,30\n2,Bo,25\n3,Cy,\n"

    def test_filter_sort_limit(self, csv_file):
        code, out, _ = self.call([csv_file, "-w", "age", ">=", "25", "-s", "age", "-n", "1"])
        assert code == 0
        assert out == "id,name,age\n2,Bo,25\n"

    def test_count(self, csv_file):
        assert self.call([csv_file, "--count"])[1] == "3\n"

    def test_unknown_column(self, csv_file):
        code, _, err = self.call([csv_file, "-c", "nope"])
        assert code == 1 and "unknown column" in err

    def test_negative_limit(self, csv_file):
        code, _, err = self.call([csv_file, "-n", "-1"])
        assert code == 1 and "limit" in err

    def test_bad_operator(self, csv_file):
        code, _, err = self.call([csv_file, "-w", "age", "=", "1"])
        assert code == 1 and "unknown operator" in err

    def test_output_file(self, csv_file, tmp_path):
        dest = tmp_path / "out.csv"
        code, out, _ = self.call([csv_file, "-o", str(dest), "-c", "name"])
        assert code == 0 and out == ""
        assert dest.read_text(encoding="utf-8") == "name\nAnn\nBo\nCy\n"

