import csv
import re

from .validation import ParseError, validate_header

# Strict numeric grammars. Python's int()/float() also accept "nan", "inf",
# "1_000" and whitespace variants, which would silently corrupt text data.
_INT_RE = re.compile(r"[+-]?\d+")
_FLOAT_RE = re.compile(r"[+-]?(?:\d+\.\d*|\.\d+|\d+)(?:[eE][+-]?\d+)?")
# Values like ZIP codes ("02134") must keep their leading zeros.
_LEADING_ZERO_RE = re.compile(r"[+-]?0\d")


def convert_value(value):
    """Convert a raw CSV string to int, float, bool, or leave it as str.

    Empty strings become None so that missing values are explicit.
    """
    if value is None:
        return None
    text = value.strip()
    if not text:
        return None
    lowered = text.lower()
    if lowered in ("true", "false"):
        return lowered == "true"
    if _LEADING_ZERO_RE.match(text):
        return text
    if _INT_RE.fullmatch(text):
        return int(text)
    if _FLOAT_RE.fullmatch(text):
        return float(text)
    return text


def parse_rows_with_header(lines, convert=True):
    """Parse CSV lines (header first) into (fieldnames, list of dicts).

    Raises ParseError for a missing/invalid header or a row whose column
    count does not match the header.
    """
    reader = csv.reader(lines)
    try:
        header = next(reader, None)
        fieldnames = validate_header(header)
        records = []
        for row in reader:
            if not row:
                continue  # skip blank lines
            if len(row) != len(fieldnames):
                raise ParseError(
                    f"line {reader.line_num}: expected {len(fieldnames)} "
                    f"fields, got {len(row)}"
