            values = [convert_value(v) for v in row] if convert else row
            records.append(dict(zip(fieldnames, values)))
    except csv.Error as exc:
        raise ParseError(f"line {reader.line_num}: {exc}") from exc
    return fieldnames, records


def parse_rows(lines, convert=True):
    """Parse an iterable of CSV lines (header first) into a list of dicts."""
    return parse_rows_with_header(lines, convert=convert)[1]


def parse_csv_with_header(path, convert=True):
    """Parse the CSV file at `path` into (fieldnames, list of dicts)."""
    try:
        # utf-8-sig strips the byte-order mark that Excel prepends.
        with open(path, newline="", encoding="utf-8-sig") as f:
            return parse_rows_with_header(f, convert=convert)
    except FileNotFoundError as exc:
        raise ParseError(f"file not found: {path}") from exc
    except UnicodeDecodeError as exc:
        raise ParseError(f"file is not valid UTF-8: {path}") from exc
    except OSError as exc:
        # Opening a directory raises IsADirectoryError on POSIX but
        # PermissionError on Windows; report both (and other I/O errors) uniformly.
        raise ParseError(f"cannot read {path}: {exc.strerror or exc}") from exc


def parse_csv(path, convert=True):
    """Parse the CSV file at `path` into a list of dicts."""
    return parse_csv_with_header(path, convert=convert)[1]

