"""SQLite storage backend with the same filter/sort semantics as operations.py.

Columns are created without a declared type, so SQLite applies no type
affinity and every value keeps the Python type the parser gave it (an int
stays an int, "007" stays text). Each column's kind is recorded in a metadata
table so booleans can be restored on read and type errors can be reported the
way the in-memory functions report them.
"""

import re
import sqlite3
import threading

from .operations import NONE_NEVER_MATCHES, OPERATORS
from .parser import parse_csv_with_header
from .validation import (
    CSVProcessingError,
    ValidationError,
    validate_header,
    validate_operator,
    validate_records,
)

META_TABLE = "_csvproc_columns"
_TABLE_RE = re.compile(r"[A-Za-z][A-Za-z0-9_]*")

NUMERIC_KINDS = {"boolean", "integer", "real"}
ORDERED_OPERATORS = {"<", "<=", ">", ">="}


class DatabaseError(CSVProcessingError):
    """SQLite reported an error."""


def value_kind(value):
    """Return the column kind of a single parsed value."""
    if value is None:
        return "null"
    if isinstance(value, bool):
        return "boolean"
    if isinstance(value, int):
        return "integer"
    if isinstance(value, float):
        return "real"
    if isinstance(value, str):
        return "text"
    raise ValidationError(f"unsupported value type {type(value).__name__}")


def merge_kinds(a, b):
    """Return the narrowest kind that holds values of kinds `a` and `b`."""
    if a == b or b == "null":
        return a
    if a == "null":
        return b
    if {a, b} == {"integer", "real"}:
        return "real"
    return "mixed"


def infer_kind(values):
    """Return the kind of a column holding `values`."""
    kind = "null"
    for value in values:
        kind = merge_kinds(kind, value_kind(value))
    return kind


def quote_ident(name):
    """Quote an SQL identifier so any CSV header text is safe to use."""
    return '"' + name.replace('"', '""') + '"'


def validate_table_name(table):
    if not isinstance(table, str) or not _TABLE_RE.fullmatch(table):
        raise ValidationError(
            f"invalid table name {table!r}: use letters, digits and underscores, "
            "starting with a letter"
        )


def _contains(field, needle, is_boolean):
    """SQL function mirroring operations.OPERATORS['contains'] exactly."""
    if field is None:
        return 0
    if is_boolean:
        field = bool(field)
    return int(str(needle).lower() in str(field).lower())


class Database:
    """A SQLite database holding one or more CSV-derived tables."""

    def __init__(self, path=":memory:"):
        try:
            # One shared connection guarded by a lock, so an in-memory database
            # can be used from the API server's worker threads.
            self.conn = sqlite3.connect(path, check_same_thread=False)
            self.conn.create_function("csvproc_contains", 3, _contains, deterministic=True)
            self.lock = threading.RLock()
            with self.conn:
                self.conn.execute(
                    f"CREATE TABLE IF NOT EXISTS {META_TABLE} ("
                    "table_name TEXT NOT NULL, position INTEGER NOT NULL, "
                    "name TEXT NOT NULL, kind TEXT NOT NULL, "
                    "PRIMARY KEY (table_name, name))"
                )
        except sqlite3.Error as exc:
            raise DatabaseError(f"cannot open database {path}: {exc}") from exc

    def close(self):
        self.conn.close()

    def __enter__(self):
        return self

    def __exit__(self, *exc_info):
        self.close()

    def _execute(self, sql, params=()):
        try:
            with self.lock:
                return self.conn.execute(sql, params).fetchall()
        except sqlite3.Error as exc:
            raise DatabaseError(str(exc)) from exc

    # -- schema -----------------------------------------------------------

    def tables(self):
        """Return the names of loaded tables."""
        rows = self._execute(f"SELECT DISTINCT table_name FROM {META_TABLE} ORDER BY table_name")
        return [r[0] for r in rows]

    def columns(self, table="records"):
        """Return [(name, kind), ...] for `table` in header order."""
        validate_table_name(table)
        rows = self._execute(
            f"SELECT name, kind FROM {META_TABLE} WHERE table_name = ? ORDER BY position",
            (table,),
        )
        if not rows:
            raise ValidationError(f"unknown table {table!r}")
        return rows

    def load(self, fieldnames, records, table="records"):
        """Create (or replace) `table` holding `records`. Returns the row count."""
        validate_table_name(table)
        fieldnames = validate_header(fieldnames)
        validate_records(records)
        expected = set(fieldnames)
        for i, record in enumerate(records):
            if set(record) != expected:
                raise ValidationError(f"record {i} fields do not match the header")
        kinds = [infer_kind(r[name] for r in records) for name in fieldnames]

        column_sql = ", ".join(quote_ident(n) for n in fieldnames)
        placeholders = ", ".join("?" for _ in fieldnames)
        rows = ([r[n] for n in fieldnames] for r in records)
        try:
            with self.lock, self.conn:
                self.conn.execute(f"DROP TABLE IF EXISTS {quote_ident(table)}")
                self.conn.execute(f"DELETE FROM {META_TABLE} WHERE table_name = ?", (table,))
                self.conn.execute(f"CREATE TABLE {quote_ident(table)} ({column_sql})")
                self.conn.executemany(
                    f"INSERT INTO {META_TABLE} VALUES (?, ?, ?, ?)",
                    [(table, i, n, k) for i, (n, k) in enumerate(zip(fieldnames, kinds))],
                )
                self.conn.executemany(
                    f"INSERT INTO {quote_ident(table)} VALUES ({placeholders})", rows
                )
        except sqlite3.Error as exc:
            raise DatabaseError(f"cannot load table {table!r}: {exc}") from exc
        return len(records)

    def load_csv(self, path, table="records"):
        """Parse the CSV at `path` and load it into `table`. Returns the row count."""
        fieldnames, records = parse_csv_with_header(path)
        return self.load(fieldnames, records, table)

    def create_index(self, column, table="records"):
        """Index `column` to speed up filtering and sorting on it."""
        kinds = dict(self.columns(table))
        if column not in kinds:
            raise ValidationError(f"unknown column {column!r}")
        index = quote_ident(f"idx_{table}_{column}")
        self._execute(f"CREATE INDEX IF NOT EXISTS {index} ON {quote_ident(table)} ({quote_ident(column)})")

    def insert(self, records, table="records"):
        """Append records (dicts keyed by column name). Returns the number inserted.

        A missing field is stored as NULL. A value must fit its column's kind;
        the only widenings allowed are from an all-null column to any kind and
        from integer to real.
        """
        validate_records(records)
        columns = self.columns(table)
        names = [n for n, _ in columns]
        kinds = dict(columns)
        for i, record in enumerate(records):
            unknown = set(record) - set(names)
            if unknown:
                raise ValidationError(f"record {i} has unknown field(s): {', '.join(sorted(unknown))}")
            for name, value in record.items():
                current, new = kinds[name], value_kind(value)
                merged = merge_kinds(current, new)
                if merged == "mixed" and current != "mixed":
                    raise ValidationError(
                        f"record {i} field {name!r}: {new} value does not fit {current} column"
                    )
                kinds[name] = merged

        placeholders = ", ".join("?" for _ in names)
        rows = [[r.get(n) for n in names] for r in records]
        try:
            with self.lock, self.conn:
                self.conn.executemany(
                    f"INSERT INTO {quote_ident(table)} VALUES ({placeholders})", rows
                )
                self.conn.executemany(
                    f"UPDATE {META_TABLE} SET kind = ? WHERE table_name = ? AND name = ?",
                    [(kinds[n], table, n) for n in names],
                )
        except sqlite3.Error as exc:
            raise DatabaseError(f"cannot insert into {table!r}: {exc}") from exc
        return len(rows)

    # -- queries ----------------------------------------------------------

    def _where(self, kinds, conditions):
        """Build a WHERE clause and its parameters from (key, op, value) triples."""
        clauses, params = [], []
        for condition in conditions:
            if not isinstance(condition, (tuple, list)) or len(condition) != 3:
                raise ValidationError(f"condition must be a (key, op, value) triple, got {condition!r}")
            key, op, value = condition
            validate_operator(op, OPERATORS)
            if key not in kinds:
                raise ValidationError(f"unknown column {key!r}")
            kind, col = kinds[key], quote_ident(key)

            if op in ORDERED_OPERATORS:
                if kind == "null":
                    clauses.append("0")  # every value is None, which never matches
                    continue
                incompatible = (
                    value is None
                    or kind == "mixed"
                    or (kind in NUMERIC_KINDS) != (value_kind(value) in NUMERIC_KINDS)
                )
                if incompatible:
                    raise ValidationError(
                        f"cannot compare field {key!r} ({kind}) with {value!r} using {op!r}"
                    )
                clauses.append(f"{col} {op} ?")
                params.append(value)
            elif op == "==":
                if value is None:
                    clauses.append(f"{col} IS NULL")
                else:
                    clauses.append(f"{col} = ?")
                    params.append(value)
            elif op == "!=":
                # In Python, None != 30 is True; in SQL, NULL != 30 is NULL.
                if value is None:
                    clauses.append(f"{col} IS NOT NULL")
                else:
                    clauses.append(f"({col} IS NULL OR {col} != ?)")
                    params.append(value)
            else:
                assert op == "contains" and op in NONE_NEVER_MATCHES
                clauses.append(f"csvproc_contains({col}, ?, {int(kind == 'boolean')})")
                params.append(value)
        return (" AND ".join(clauses) or "1"), params

    def query(self, table="records", conditions=(), sort=None, reverse=False,
              limit=None, offset=0, columns=None):
        """Return matching records as dicts, like apply_filters + sort_records."""
        kinds = dict(self.columns(table))
        selected = list(kinds) if columns is None else list(columns)
        unknown = [c for c in selected if c not in kinds]
        if unknown:
            raise ValidationError(f"unknown column(s): {', '.join(unknown)}")
        if not selected:
            raise ValidationError("at least one column must be selected")

        where, params = self._where(kinds, conditions)
        sql = f"SELECT {', '.join(quote_ident(c) for c in selected)} FROM {quote_ident(table)} WHERE {where}"

        if sort is not None:
            if sort not in kinds:
                raise ValidationError(f"unknown column {sort!r}")
            if kinds[sort] == "mixed":
                raise ValidationError(f"field {sort!r} contains values of incomparable types")
            col = quote_ident(sort)
            # Missing values last regardless of direction; rowid keeps the sort
            # stable, matching Python's sorted().
            sql += f" ORDER BY {col} IS NULL, {col} {'DESC' if reverse else 'ASC'}, rowid"
        else:
            sql += " ORDER BY rowid"

        for name, value in (("limit", limit), ("offset", offset)):
            if value is not None and (not isinstance(value, int) or isinstance(value, bool) or value < 0):
                raise ValidationError(f"{name} must be a non-negative integer")
        sql += " LIMIT ? OFFSET ?"
        params += [-1 if limit is None else limit, offset or 0]

        booleans = [i for i, c in enumerate(selected) if kinds[c] == "boolean"]
        result = []
        for row in self._execute(sql, params):
            row = list(row)
            for i in booleans:
                if row[i] is not None:
                    row[i] = bool(row[i])
            result.append(dict(zip(selected, row)))
        return result

    def count(self, table="records", conditions=()):
        """Return the number of records matching `conditions`."""
        kinds = dict(self.columns(table))
        where, params = self._where(kinds, conditions)
        return self._execute(f"SELECT COUNT(*) FROM {quote_ident(table)} WHERE {where}", params)[0][0]

