"""JSON HTTP API over a SQLite-backed CSV table.

Endpoints (all accept ?table=NAME, default "records"):
  GET  /health                      -> {"status": "ok"}
  GET  /tables                      -> {"tables": [...]}
  GET  /columns                     -> {"columns": [{"name", "kind"}, ...]}
  GET  /records                     -> {"records": [...], "count": n}
       ?where=KEY:OP:VALUE (repeatable, ANDed)  &sort=KEY  &reverse=true
       &limit=N  &offset=N  &columns=a,b  &format=json|csv
  GET  /records/count               -> {"count": n}     (accepts where=)
  POST /records  JSON object or list -> 201 {"inserted": n}
"""

import argparse
import io
import json
import sys
from http import HTTPStatus
from http.server import BaseHTTPRequestHandler, ThreadingHTTPServer
from urllib.parse import parse_qs, urlsplit

from .cli import build_conditions, write_records
from .db import Database, DatabaseError
from .validation import CSVProcessingError, ValidationError

MAX_BODY_BYTES = 1_000_000

# Allowed query parameters per route; anything else is rejected so typos
# like ?sorrt=age fail loudly instead of being ignored.
ROUTE_PARAMS = {
    "/health": set(),
    "/tables": set(),
    "/columns": {"table"},
    "/records": {"table", "where", "sort", "reverse", "limit", "offset", "columns", "format"},
    "/records/count": {"table", "where"},
}


class ApiError(Exception):
    """An error with an HTTP status, reported to the client as JSON."""

    def __init__(self, status, message):
        super().__init__(message)
        self.status = status
        self.message = message


def parse_where(text):
    """Parse KEY:OP:VALUE (VALUE may itself contain colons)."""
    parts = text.split(":", 2)
    if len(parts) != 3 or not parts[0] or not parts[1]:
        raise ValidationError(f"where must look like KEY:OP:VALUE, got {text!r}")
    return parts


def parse_bool(name, text):
    lowered = text.lower()
    if lowered in ("true", "1", "yes"):
        return True
    if lowered in ("false", "0", "no"):
        return False
    raise ValidationError(f"{name} must be true or false, got {text!r}")


def parse_int(name, text):
    try:
        value = int(text)
    except ValueError:
        raise ValidationError(f"{name} must be an integer, got {text!r}") from None
    if value < 0:
        raise ValidationError(f"{name} must be non-negative")
    return value


def single(params, name, default=None):
    """Return the one value of query parameter `name`, or `default`."""
    values = params.get(name)
    if values is None:
        return default
    if len(values) > 1:
        raise ValidationError(f"parameter {name!r} given more than once")
    return values[0]


def parse_query(path, query):
    """Validate the query string for `path` and return it as a dict of lists."""
    params = parse_qs(query, keep_blank_values=True, strict_parsing=False)
    unknown = set(params) - ROUTE_PARAMS[path]
    if unknown:
        raise ValidationError(f"unknown query parameter(s): {', '.join(sorted(unknown))}")
    return params


def query_options(params):
    """Translate /records query parameters into Database.query keyword arguments."""
    options = {
        "table": single(params, "table", "records"),
        "conditions": build_conditions(parse_where(w) for w in params.get("where", [])),
        "sort": single(params, "sort"),
        "reverse": parse_bool("reverse", single(params, "reverse", "false")),
    }
    for name in ("limit", "offset"):
        text = single(params, name)
        if text is not None:
            options[name] = parse_int(name, text)
    columns = single(params, "columns")
    if columns is not None:
        options["columns"] = [c.strip() for c in columns.split(",") if c.strip()]
    return options


def _reject_constant(name):
    raise ValueError(f"{name} is not valid JSON")


class Handler(BaseHTTPRequestHandler):
    server_version = "csvproc/1.0"

    @property
    def db(self):
        return self.server.db

    def log_message(self, format, *args):
        if getattr(self.server, "verbose", False):
            super().log_message(format, *args)

    # -- responses --------------------------------------------------------

    def send_body(self, status, body, content_type):
        self.send_response(status)
        self.send_header("Content-Type", content_type)
        self.send_header("Content-Length", str(len(body)))
        self.end_headers()
        self.wfile.write(body)

    def send_json(self, status, payload):
        body = json.dumps(payload, allow_nan=False).encode("utf-8")
        self.send_body(status, body, "application/json")

    def handle_request(self, handler):
        try:
            handler()
        except ApiError as exc:
            self.send_json(exc.status, {"error": exc.message})
        except DatabaseError as exc:
            self.send_json(HTTPStatus.INTERNAL_SERVER_ERROR, {"error": f"database error: {exc}"})
        except CSVProcessingError as exc:
            self.send_json(HTTPStatus.BAD_REQUEST, {"error": str(exc)})
        except Exception:  # never leak a traceback to the client
            self.log_error("unhandled error on %s %s", self.command, self.path)
            self.send_json(HTTPStatus.INTERNAL_SERVER_ERROR, {"error": "internal server error"})

    # -- routing ----------------------------------------------------------

    def route(self, allowed):
        url = urlsplit(self.path)
        path = url.path.rstrip("/") or "/"
        if path not in ROUTE_PARAMS:
            raise ApiError(HTTPStatus.NOT_FOUND, f"no such endpoint: {path}")
        if path not in allowed:
            raise ApiError(HTTPStatus.METHOD_NOT_ALLOWED, f"{self.command} not allowed on {path}")
        return path, parse_query(path, url.query)

    def do_GET(self):
        self.handle_request(self._get)

    def do_POST(self):
        self.handle_request(self._post)

    def _not_allowed(self):
        def fail():
            self.route(set())  # 404 for unknown paths
            raise ApiError(HTTPStatus.METHOD_NOT_ALLOWED, f"{self.command} not allowed")
        self.handle_request(fail)

    do_PUT = do_DELETE = do_PATCH = _not_allowed

    def _get(self):
        path, params = self.route({"/health", "/tables", "/columns", "/records", "/records/count"})
        if path == "/health":
            self.send_json(HTTPStatus.OK, {"status": "ok"})
        elif path == "/tables":
            self.send_json(HTTPStatus.OK, {"tables": self.db.tables()})
        elif path == "/columns":
            columns = self.db.columns(single(params, "table", "records"))
            self.send_json(HTTPStatus.OK, {"columns": [{"name": n, "kind": k} for n, k in columns]})
        elif path == "/records/count":
            table = single(params, "table", "records")
            conditions = build_conditions(parse_where(w) for w in params.get("where", []))
            self.send_json(HTTPStatus.OK, {"count": self.db.count(table, conditions)})
        else:
            fmt = single(params, "format", "json")
            if fmt not in ("json", "csv"):
                raise ValidationError(f"format must be json or csv, got {fmt!r}")
            options = query_options(params)
            records = self.db.query(**options)
            if fmt == "json":
                self.send_json(HTTPStatus.OK, {"records": records, "count": len(records)})
            else:
                columns = options.get("columns") or [n for n, _ in self.db.columns(options["table"])]
                out = io.StringIO()
                write_records(records, out, columns)
                self.send_body(HTTPStatus.OK, out.getvalue().encode("utf-8"), "text/csv; charset=utf-8")

    def _post(self):
        path, params = self.route({"/records"})
        table = single(params, "table", "records")
        if params.keys() - {"table"}:
            raise ValidationError("POST /records accepts only the table parameter")

        content_type = self.headers.get("Content-Type", "").split(";")[0].strip().lower()
        if content_type != "application/json":
            raise ApiError(HTTPStatus.UNSUPPORTED_MEDIA_TYPE, "Content-Type must be application/json")
        length_header = self.headers.get("Content-Length")
        if length_header is None:
            raise ApiError(HTTPStatus.LENGTH_REQUIRED, "Content-Length is required")
        try:
            length = int(length_header)
        except ValueError:
            raise ApiError(HTTPStatus.BAD_REQUEST, "invalid Content-Length") from None
        if length < 0:
            raise ApiError(HTTPStatus.BAD_REQUEST, "invalid Content-Length")
        if length > MAX_BODY_BYTES:
            raise ApiError(HTTPStatus.REQUEST_ENTITY_TOO_LARGE,
                           f"body exceeds {MAX_BODY_BYTES} bytes")

        raw = self.rfile.read(length)
        try:
            payload = json.loads(raw.decode("utf-8"), parse_constant=_reject_constant)
        except (UnicodeDecodeError, ValueError) as exc:
            raise ApiError(HTTPStatus.BAD_REQUEST, f"invalid JSON body: {exc}") from None

        records = [payload] if isinstance(payload, dict) else payload
        if not isinstance(records, list) or not records:
            raise ValidationError("body must be a JSON object or a non-empty list of objects")
        inserted = self.db.insert(records, table)
        self.send_json(HTTPStatus.CREATED, {"inserted": inserted})


def make_server(db, host="127.0.0.1", port=8000, verbose=False):
    """Create (but do not start) an API server bound to host:port."""
    server = ThreadingHTTPServer((host, port), Handler)
    server.daemon_threads = True
    server.db = db
    server.verbose = verbose
    return server


def main(argv=None):
    parser = argparse.ArgumentParser(prog="csvproc.api", description="Serve a CSV file over HTTP.")
    parser.add_argument("file", help="CSV file to load")
    parser.add_argument("--db", default=":memory:", help="SQLite database path (default: in memory)")
    parser.add_argument("--table", default="records", help="table name (default: records)")
    parser.add_argument("--index", default="", help="comma-separated columns to index")
    parser.add_argument("--host", default="127.0.0.1")
    parser.add_argument("--port", type=int, default=8000)
    parser.add_argument("-v", "--verbose", action="store_true", help="log each request")
    args = parser.parse_args(argv)

    try:
        db = Database(args.db)
        count = db.load_csv(args.file, args.table)
        for column in filter(None, (c.strip() for c in args.index.split(","))):
            db.create_index(column, args.table)
    except CSVProcessingError as exc:
        print(f"error: {exc}", file=sys.stderr)
        return 1

    try:
        server = make_server(db, args.host, args.port, args.verbose)
    except OSError as exc:
        print(f"error: cannot listen on {args.host}:{args.port}: {exc.strerror or exc}", file=sys.stderr)
        return 1
    host, port = server.server_address[:2]
    print(f"Loaded {count} rows into {args.table!r}; serving on http://{host}:{port}", flush=True)
    try:
        server.serve_forever()
    except KeyboardInterrupt:
        pass
    finally:
        server.server_close()
        db.close()
    return 0


if __name__ == "__main__":
    sys.exit(main())

